/**
 * StreamX Cloudflare Worker — 24/7 Edge Proxy & Direct Google Drive Streamer
 * 
 * Runs 24/7 on Cloudflare's serverless edge network (100% in cloud, ZERO cost, NO credit card).
 * 
 * Dual-Mode Architecture:
 * 1. ONLINE MODE (When your PC is ON):
 *    - Forwards all API requests to your local backend via Cloudflare Tunnel.
 *    - Caches media catalog & image proxies on Cloudflare edge.
 * 2. OFFLINE MODE (When your PC is OFF):
 *    - Serves the cached media catalog 24/7 so the website is always reachable.
 *    - Streams videos directly from Google Drive to your browser or VLC with HTTP 206 Partial Content.
 *    - Generates M3U playlists on the fly for external media players (VLC, MX Player, IINA).
 *    - Zero bandwidth limit: 100% free streaming powered by Google Drive & Cloudflare Edge.
 */

// Upstream backend tunnel configuration
let dynamicBackendUrl = null;
let lastTunnelFetch = 0;

// Update deduplication set (in-memory ring buffer)
const PROCESSED_UPDATE_IDS = new Set();
const MAX_PROCESSED_UPDATE_HISTORY = 1000;

function isDuplicateUpdate(updateId) {
  if (!updateId) return false;
  if (PROCESSED_UPDATE_IDS.has(updateId)) return true;
  if (PROCESSED_UPDATE_IDS.size >= MAX_PROCESSED_UPDATE_HISTORY) {
    const oldest = PROCESSED_UPDATE_IDS.values().next().value;
    PROCESSED_UPDATE_IDS.delete(oldest);
  }
  PROCESSED_UPDATE_IDS.add(updateId);
  return false;
}

function isValidBackendUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== "string") return false;
  try {
    const u = new URL(rawUrl.trim());
    if (u.protocol !== "https:" && u.protocol !== "http:") return false;
    const host = u.hostname.toLowerCase();
    return (
      host === "localhost" ||
      host === "127.0.0.1" ||
      host.endsWith(".trycloudflare.com") ||
      host.endsWith(".onrender.com") ||
      host.endsWith(".workers.dev")
    );
  } catch {
    return false;
  }
}

async function getLiveBackendUrl(env) {
  const now = Date.now();
  if (dynamicBackendUrl && (now - lastTunnelFetch < 30000)) {
    return dynamicBackendUrl;
  }
  if (env?.BACKEND_URL && env.BACKEND_URL.trim()) {
    const candidate = env.BACKEND_URL.trim().replace(/\/+$/, "");
    if (isValidBackendUrl(candidate)) {
      dynamicBackendUrl = candidate;
      lastTunnelFetch = now;
      return dynamicBackendUrl;
    }
  }
  try {
    const res = await fetch("https://raw.githubusercontent.com/siddiqx/StreamX/main/active_tunnel.txt", {
      headers: { "Cache-Control": "no-cache" },
      signal: AbortSignal.timeout(3000),
    });
    if (res.ok) {
      const txt = (await res.text()).trim();
      if (txt && isValidBackendUrl(txt)) {
        dynamicBackendUrl = txt.replace(/\/+$/, "");
        lastTunnelFetch = now;
        return dynamicBackendUrl;
      }
    }
  } catch (_) {}
  return "";
}

// In-memory token cache for Google OAuth
let cachedGoogleToken = null;
let googleTokenExpiry = 0;

// In-memory catalog cache for 24/7 offline fallback
let cachedCatalog = null;
let cachedCatalogTime = 0;

async function getGoogleAccessToken(env, forceRefresh = false) {
  const now = Date.now();
  if (!forceRefresh && cachedGoogleToken && googleTokenExpiry > now + 60000) {
    return cachedGoogleToken;
  }

  const clientId = env?.GOOGLE_CLIENT_ID?.trim();
  const clientSecret = env?.GOOGLE_CLIENT_SECRET?.trim();
  const refreshToken = env?.GOOGLE_REFRESH_TOKEN?.trim();

  if (!clientId || !clientSecret || !refreshToken) {
    throw new Error(
      "Google Drive OAuth credentials are not configured. Please configure GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, and GOOGLE_REFRESH_TOKEN in Cloudflare Worker secrets."
    );
  }

  const params = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    refresh_token: refreshToken,
    grant_type: "refresh_token",
  });

  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Google OAuth refresh failed HTTP ${res.status}: ${errText}`);
  }

  const data = await res.json();
  if (!data.access_token) {
    throw new Error("Google OAuth did not return an access_token.");
  }

  cachedGoogleToken = data.access_token;
  googleTokenExpiry = now + (data.expires_in || 3600) * 1000;
  return cachedGoogleToken;
}

// --- 24/7 Telegram Edge Bot Webhook Engine ---
async function handleTelegramWebhook(request, env, rawBase) {
  try {
    // 1. Enforce payload size boundary (max 512KB for Telegram update JSON)
    const contentLength = parseInt(request.headers.get("Content-Length") || "0", 10);
    if (contentLength > 1024 * 512) {
      return new Response(JSON.stringify({ error: "Payload too large" }), {
        status: 413,
        headers: { "Content-Type": "application/json" },
      });
    }

    // 2. Validate Telegram webhook secret token header
    if (env?.TELEGRAM_WEBHOOK_SECRET) {
      const secretToken = request.headers.get("X-Telegram-Bot-Api-Secret-Token");
      if (!secretToken || secretToken !== env.TELEGRAM_WEBHOOK_SECRET) {
        return new Response(JSON.stringify({ error: "Invalid webhook secret token" }), {
          status: 403,
          headers: { "Content-Type": "application/json" },
        });
      }
    }

    // 3. Retrieve bot token securely from environment secrets only
    const botToken = env?.TELEGRAM_BOT_TOKEN?.trim();
    if (!botToken) {
      return new Response(JSON.stringify({ error: "TELEGRAM_BOT_TOKEN not configured" }), {
        status: 503,
        headers: { "Content-Type": "application/json" },
      });
    }

    const ownerId = parseInt(env?.TELEGRAM_OWNER_USER_ID || "8142877259", 10);
    const allowedRaw = env?.TELEGRAM_ALLOWED_USER_IDS || "8142877259,7344705202,8640979779";
    const allowedUsers = allowedRaw.split(",").map((s) => parseInt(s.trim(), 10)).filter(Boolean);

    const sendTelegram = async (chatId, text, replyId) => {
      try {
        const payload = { chat_id: chatId, text, parse_mode: "HTML" };
        if (replyId) payload.reply_to_message_id = replyId;
        await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
      } catch (e) {
        console.error("sendTelegram error:", e);
      }
    };

    const forwardToOwner = async (fromChatId, messageId) => {
      try {
        const res = await fetch(`https://api.telegram.org/bot${botToken}/forwardMessage`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            chat_id: ownerId,
            from_chat_id: fromChatId,
            message_id: messageId,
          }),
        });
        return res.ok;
      } catch (e) {
        console.error("forwardToOwner error:", e);
        return false;
      }
    };

    const update = await request.json();

    // 4. Prevent duplicate replay attacks
    if (update.update_id && isDuplicateUpdate(update.update_id)) {
      return new Response("OK", { status: 200 });
    }

    const msg = update.message || update.channel_post || update.edited_message;
    if (!msg) return new Response("OK", { status: 200 });

    const chatId = msg.chat?.id;
    const userId = msg.from?.id || chatId;
    const msgId = msg.message_id;

    if (!chatId || !userId) return new Response("OK", { status: 200 });

    // Authorization check
    if (!allowedUsers.includes(userId)) {
      await sendTelegram(chatId, "⛔ <b>Access Denied</b>\nThis StreamX Bot instance is private.", msgId);
      return new Response("OK", { status: 200 });
    }

    // 5. When your PC is running and backend is valid, proxy directly to the local backend.
    let handledByBackend = false;
    if (rawBase) {
      try {
        const fwdHeaders = { "Content-Type": "application/json" };
        if (env?.TELEGRAM_WEBHOOK_SECRET) {
          fwdHeaders["X-Telegram-Bot-Api-Secret-Token"] = env.TELEGRAM_WEBHOOK_SECRET;
        }
        const backendRes = await fetch(`${rawBase}/telegram/webhook`, {
          method: "POST",
          headers: fwdHeaders,
          body: JSON.stringify(update),
          signal: AbortSignal.timeout(6000),
        });
        if (backendRes.ok) {
          handledByBackend = true;
        }
      } catch (_) {
        handledByBackend = false;
      }
    }

    if (handledByBackend) {
      return new Response("OK", { status: 200 });
    }

    // --- PC IS OFFLINE / BACKEND UNREACHABLE: 24/7 EDGE FALLBACK MODE ---
    const text = (msg.text || msg.caption || "").trim();
    const cmd = text.split(/\s+/)[0].toLowerCase().split("@")[0];

    // Commands in Edge Mode
    if (cmd === "/start") {
      await sendTelegram(
        chatId,
        `👋 <b>Welcome to StreamX!</b>\n\n` +
        `StreamX is your personal media cloud pipeline connecting Telegram directly to Google Drive.\n\n` +
        `<b>Features:</b>\n` +
        `• <b>24/7 Cloud Ingestion:</b> Forward any video, episode, or movie directly to this bot at any time.\n` +
        `• <b>Edge Responding:</b> This bot is always online and ready to accept your files.\n` +
        `• <b>Automatic Downloads:</b> When your PC is running, all queued files stream directly to Google Drive.\n\n` +
        `<b>Commands:</b>\n` +
        `• /status — Check 24/7 edge & download status\n` +
        `• /queue — Active download queue\n` +
        `• /library — Media library overview\n` +
        `• /ping — Test edge responsiveness\n` +
        `• /help — Full instructions`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    if (cmd === "/ping") {
      await sendTelegram(
        chatId,
        `🏓 <b>Pong! StreamX is Online 24/7</b>\n\n` +
        `🟢 <b>Edge Gateway:</b> Cloudflare Serverless Active\n` +
        `☁️ <b>Google Drive:</b> Connected & Ready\n` +
        `📥 <b>Queue Engine:</b> Ready for new transfers`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    if (cmd === "/help") {
      await sendTelegram(
        chatId,
        `📖 <b>StreamX Help Guide</b>\n\n` +
        `• <b>Forward Media:</b> Forward any anime, movie, or series episode directly to this bot.\n` +
        `• <b>24/7 Cloud Ingestion:</b> Your files are safely accepted anytime.\n` +
        `• <b>Automatic Download:</b> When PC turns on, downloads begin automatically.\n` +
        `• <b>VLC Playback:</b> Click Play on the StreamX site or PWA to open directly in VLC.`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    if (cmd === "/status" || cmd === "/queue") {
      await sendTelegram(
        chatId,
        `📊 <b>StreamX System Status</b>\n\n` +
        `🟢 <b>Edge Bot Engine:</b> Active 24/7 (Always Responding)\n` +
        `💻 <b>Download Worker:</b> 🟡 Standby (PC is offline — queued files will automatically download when your PC turns on)\n` +
        `☁️ <b>Google Drive:</b> Connected 24/7`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    if (cmd === "/library") {
      await sendTelegram(
        chatId,
        `📚 <b>StreamX Media Library</b>\n\n` +
        `Your entire library is accessible 24/7 on the StreamX web app and PWA.\n` +
        `Click <b>Play</b> on any item to stream directly in VLC.`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    // Media Handling (Video, Document, Audio, Animation)
    const mediaObj = msg.document || msg.video || msg.animation || msg.audio;
    if (mediaObj) {
      const fileName = mediaObj.file_name || msg.caption || `media_${Date.now()}.mp4`;
      const fileSize = mediaObj.file_size || 0;
      const sizeMb = (fileSize / (1024 * 1024)).toFixed(1);

      // Forward to owner account so MTProto user can read it
      if (userId !== ownerId) {
        await forwardToOwner(chatId, msgId);
      }

      await sendTelegram(
        chatId,
        `🎬 <b>StreamX — Media Received & Queued 24/7</b>\n\n` +
        `📁 <b>File:</b> <code>${fileName}</code>\n` +
        `📦 <b>Size:</b> ${sizeMb} MB\n` +
        `⚡ <b>Status:</b> <code>Queued in cloud</code>\n` +
        `🏷️ <b>Forwarded:</b> Saved to download queue\n\n` +
        `<i>Your file is safely queued in the cloud. It will automatically download to Google Drive as soon as your PC is running!</i>`,
        msgId
      );
      return new Response("OK", { status: 200 });
    }

    // Fallback for plain text
    await sendTelegram(
      chatId,
      `💡 <b>Forward a media file to start</b>\n\n` +
      `Send or forward any video, movie, episode, or document directly to this bot to transfer it to Google Drive.\n\n` +
      `Type /help for instructions or /status for status.`,
      msgId
    );
    return new Response("OK", { status: 200 });
  } catch (err) {
    return new Response(JSON.stringify({ error: err.message }), { status: 200 });
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const origin = request.headers.get("Origin") || "*";

    // Handle CORS preflight (OPTIONS)
    if (request.method === "OPTIONS") {
      const reqHeaders = request.headers.get("Access-Control-Request-Headers") || "*";
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": origin,
          "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, PATCH, OPTIONS, HEAD",
          "Access-Control-Allow-Headers": reqHeaders,
          "Access-Control-Allow-Credentials": "true",
          "Access-Control-Max-Age": "86400",
        },
      });
    }

    const rawBase = await getLiveBackendUrl(env);

    // 24/7 Telegram Webhook handler
    if ((url.pathname === "/telegram/webhook" || url.pathname === "/api/telegram/webhook") && request.method === "POST") {
      return await handleTelegramWebhook(request, env, rawBase);
    }

    if (!rawBase && !isStream && !isPlaylist && !isCatalog && url.pathname !== "/health" && url.pathname !== "/system/status" && !url.pathname.startsWith("/media/image-proxy")) {
      return new Response(JSON.stringify({ status: "edge_mode", message: "Backend is currently offline or unreachable." }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": origin },
      });
    }

    const targetUrl = new URL(rawBase + url.pathname + url.search);
    const isStream = url.pathname.includes("/stream");
    const isPlaylist = url.pathname.includes("/playlist.m3u");
    const isCatalog = url.pathname === "/media";
    const driveIdParam = url.searchParams.get("drive_id");

    // Helper: Stream directly from Google Drive
    const streamDirectFromDrive = async (driveFileId) => {
      try {
        let token = await getGoogleAccessToken(env);
        const driveUrl = `https://www.googleapis.com/drive/v3/files/${driveFileId}?alt=media`;

        const getHeaders = (tok) => {
          const h = new Headers();
          h.set("Authorization", `Bearer ${tok}`);
          const range = request.headers.get("Range");
          if (range) h.set("Range", range);
          return h;
        };

        let driveRes = await fetch(driveUrl, {
          method: request.method,
          headers: getHeaders(token),
        });

        // If Google token expired, refresh and retry once
        if (driveRes.status === 401) {
          cachedGoogleToken = null;
          token = await getGoogleAccessToken(env, true);
          driveRes = await fetch(driveUrl, {
            method: request.method,
            headers: getHeaders(token),
          });
        }

        const resHeaders = new Headers(driveRes.headers);
        resHeaders.set("Access-Control-Allow-Origin", origin);
        resHeaders.set("Access-Control-Allow-Credentials", "true");
        resHeaders.set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges, Content-Disposition");
        resHeaders.set("Accept-Ranges", "bytes");

        let ctype = resHeaders.get("Content-Type") || "";
        if (!ctype || ctype.includes("octet-stream") || ctype.includes("x-download")) {
          ctype = url.pathname.toLowerCase().endsWith(".mp4") ? "video/mp4" : "video/x-matroska";
          resHeaders.set("Content-Type", ctype);
        }
        resHeaders.set("Content-Disposition", "inline");

        return new Response(request.method === "HEAD" ? null : driveRes.body, {
          status: driveRes.status,
          statusText: driveRes.statusText,
          headers: resHeaders,
        });
      } catch (driveErr) {
        return new Response(
          JSON.stringify({
            error: "Failed to stream directly from Google Drive",
            message: driveErr.message,
          }),
          {
            status: 502,
            headers: {
              "Content-Type": "application/json",
              "Access-Control-Allow-Origin": origin,
            },
          }
        );
      }
    };

    // 1. Instant 24/7 M3U Playlist Generation (Direct Play at Cloudflare Edge)
    if (isPlaylist) {
      let targetDriveId = driveIdParam;
      if (!targetDriveId) {
        const match = url.pathname.match(/\/media\/(\d+)\/playlist/);
        if (match) {
          const mediaId = parseInt(match[1], 10);
          const catalogData = cachedCatalog || FALLBACK_CATALOG;
          const found = catalogData.find((item) => item.id === mediaId);
          if (found && found.drive_file_id) targetDriveId = found.drive_file_id;
        }
      }
      if (targetDriveId) {
        const streamUrl = `https://${url.host}/media/0/stream/stream.mkv?drive_id=${encodeURIComponent(targetDriveId)}`;
        const m3u = `#EXTM3U\n#EXTINF:-1,StreamX Direct Play\n${streamUrl}\n`;
        return new Response(m3u, {
          status: 200,
          headers: {
            "Content-Type": "application/x-mpegurl; charset=utf-8",
            "Access-Control-Allow-Origin": origin,
            "Access-Control-Allow-Credentials": "true",
          },
        });
      }
    }

    // 2. Instant 24/7 Direct Stream (Bypasses home PC tunnel for 0ms startup, zero home upload bandwidth usage)
    if (isStream && !url.pathname.includes("/compatible")) {
      let targetDriveId = driveIdParam;
      if (!targetDriveId) {
        const match = url.pathname.match(/\/media\/(\d+)\/stream/);
        if (match) {
          const mediaId = parseInt(match[1], 10);
          const catalogData = cachedCatalog || FALLBACK_CATALOG;
          const found = catalogData.find((item) => item.id === mediaId);
          if (found && found.drive_file_id) targetDriveId = found.drive_file_id;
        }
      }
      if (targetDriveId) {
        return await streamDirectFromDrive(targetDriveId);
      }
    }

    // Forward original headers to local backend
    const newHeaders = new Headers(request.headers);
    newHeaders.set("Host", targetUrl.host);
    newHeaders.set("X-Forwarded-Host", url.host);
    newHeaders.set("X-Forwarded-Proto", "https");

    const fetchInit = {
      method: request.method,
      headers: newHeaders,
      body: ["GET", "HEAD"].includes(request.method) ? undefined : request.body,
      redirect: "follow",
    };
    if (fetchInit.body && typeof fetchInit.body === "object") {
      fetchInit.duplex = "half";
    }

    try {
      // 1. Attempt to reach backend tunnel
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), isStream ? 5000 : 3500);
      fetchInit.signal = controller.signal;

      const response = await fetch(targetUrl.toString(), fetchInit);
      clearTimeout(timeoutId);

      // If tunnel returned server error (502, 503, 504, 520, 521, 522, 523, 530), treat as tunnel down
      if (response.status >= 500) {
        throw new Error(`Backend tunnel unreachable or returned HTTP ${response.status}`);
      }

      // Cache catalog response on success
      if (isCatalog && response.status === 200) {
        try {
          const clone = response.clone();
          cachedCatalog = await clone.json();
          cachedCatalogTime = Date.now();
        } catch (_) {}
      }

      // Clone response headers and attach CORS
      const resHeaders = new Headers(response.headers);
      resHeaders.set("Access-Control-Allow-Origin", origin);
      resHeaders.set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, PATCH, OPTIONS, HEAD");
      resHeaders.set("Access-Control-Allow-Headers", "*");
      resHeaders.set("Access-Control-Allow-Credentials", "true");
      resHeaders.set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges");

      const hasNoBody = [101, 204, 205, 304].includes(response.status) || request.method === "HEAD";

      return new Response(hasNoBody ? null : response.body, {
        status: response.status,
        statusText: response.statusText,
        headers: resHeaders,
      });
    } catch (err) {
      // 2. OFFLINE FALLBACK (When local PC is off or tunnel is down)
      const catalogData = (cachedCatalog && Array.isArray(cachedCatalog) && cachedCatalog.length > 0)
        ? cachedCatalog
        : FALLBACK_CATALOG;

      // Fallback A: Stream video directly from Google Drive
      if (isStream && driveIdParam) {
        return await streamDirectFromDrive(driveIdParam);
      }

      // Fallback B: If stream requested without drive_id param, resolve from catalog
      if (isStream) {
        const match = url.pathname.match(/\/media\/(\d+)\/stream/);
        if (match && catalogData && Array.isArray(catalogData)) {
          const mediaId = parseInt(match[1], 10);
          const found = catalogData.find((item) => item.id === mediaId);
          if (found && found.drive_file_id) {
            return await streamDirectFromDrive(found.drive_file_id);
          }
        }
      }

      // Fallback C: Generate M3U playlist pointing to direct stream
      if (isPlaylist) {
        let targetDriveId = driveIdParam;
        if (!targetDriveId) {
          const match = url.pathname.match(/\/media\/(\d+)\/playlist/);
          if (match && catalogData && Array.isArray(catalogData)) {
            const mediaId = parseInt(match[1], 10);
            const found = catalogData.find((item) => item.id === mediaId);
            if (found && found.drive_file_id) targetDriveId = found.drive_file_id;
          }
        }
        if (targetDriveId) {
          const streamUrl = `https://${url.host}/media/0/stream/stream.mkv?drive_id=${encodeURIComponent(targetDriveId)}`;
          const m3u = `#EXTM3U\n#EXTINF:-1,StreamX Direct Play\n${streamUrl}\n`;
          return new Response(m3u, {
            status: 200,
            headers: {
              "Content-Type": "application/x-mpegurl; charset=utf-8",
              "Access-Control-Allow-Origin": origin,
              "Access-Control-Allow-Credentials": "true",
            },
          });
        }
      }

      // Fallback D: Serve catalog so frontend displays library 24/7 without HTTP 503
      if (isCatalog) {
        return new Response(JSON.stringify(catalogData), {
          status: 200,
          headers: {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": origin,
            "Access-Control-Allow-Credentials": "true",
            "X-StreamX-Source": "edge-catalog-24-7",
          },
        });
      }

      // Fallback E: System health check
      if (url.pathname === "/health" || url.pathname === "/system/status" || url.pathname === "/api/health") {
        return new Response(
          JSON.stringify({
            status: "online",
            edge: "Cloudflare Worker 24/7",
            backend: "offline (local PC sleeping)",
            streaming: "ready (direct Google Drive)",
            catalog_count: catalogData.length,
          }),
          {
            status: 200,
            headers: {
              "Content-Type": "application/json",
              "Access-Control-Allow-Origin": origin,
            },
          }
        );
      }

      // Fallback F: Image Proxy for TMDB posters when PC is offline (with SSRF protection)
      if (url.pathname.startsWith("/media/image-proxy") || url.pathname.startsWith("/api/media/image-proxy")) {
        const targetImg = url.searchParams.get("url");
        if (targetImg) {
          try {
            const parsedImg = new URL(targetImg);
            const allowedHosts = ["image.tmdb.org", "s4.anilist.co", "anilist.co"];
            if (parsedImg.protocol === "https:" && allowedHosts.includes(parsedImg.hostname.toLowerCase())) {
              const imgRes = await fetch(targetImg);
              const imgHeaders = new Headers(imgRes.headers);
              imgHeaders.set("Access-Control-Allow-Origin", origin);
              imgHeaders.set("Cache-Control", "public, max-age=604800, immutable");
              return new Response(imgRes.body, {
                status: imgRes.status,
                headers: imgHeaders,
              });
            } else {
              return new Response(JSON.stringify({ error: "Only official TMDB or AniList image hosts are permitted." }), {
                status: 400,
                headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": origin },
              });
            }
          } catch (_) {
            return new Response(JSON.stringify({ error: "Invalid image URL." }), {
              status: 400,
              headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": origin },
            });
          }
        }
      }

      // Fallback G: Active transfers / queue check when PC is offline
      if (url.pathname === "/transfers" || url.pathname === "/api/transfers") {
        return new Response(JSON.stringify([]), {
          status: 200,
          headers: {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": origin,
            "Access-Control-Allow-Credentials": "true",
          },
        });
      }

      // Default Edge Response: Return 200 with edge info instead of 503 error
      return new Response(
        JSON.stringify({
          status: "edge_mode",
          message: "StreamX 24/7 Edge is online. Local PC is offline. Direct Google Drive streaming is ready.",
          catalog_count: catalogData.length,
        }),
        {
          status: 200,
          headers: {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": origin,
            "Access-Control-Allow-Credentials": "true",
          },
        }
      );
    }
  },
};
